pub fn simple_nested(a: &mut Vec<i32>, b: &Vec<i32>, N: i32) -> i32 {
    let n = N as usize;

    let mut sum = 0;
    for i in 0..n {
        // According to problem:
        // b[i] == i or i+1
        // set a[i] = 1 if b[i] == i, else 2
        let val = if b[i] == i as i32 { 1 } else { 2 };
        a[i] = val;
        sum += val;
    }

    sum
}